function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // drawing a clock for time, 10 hours 8 minutes and 4 seconds
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();
  // hour hand
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 80 * Math.sin(2 * Math.PI * (10/12 + t/10)), 
              H/2 - 80 * Math.cos(2 * Math.PI * (10/12 + t/10)));
  ctx.stroke();
  // minute hand
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 90 * Math.sin(2 * Math.PI * (8/60 + t/5)), 
              H/2 - 90 * Math.cos(2 * Math.PI * (8/60 + t/5)));
  ctx.stroke();
  // second hand
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 100 * Math.sin(2 * Math.PI * (4/60 + t)), 
              H/2 - 100 * Math.cos(2 * Math.PI * (4/60 + t)));
  ctx.stroke();
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('10:08:04', W/2, H/2 + 120);
  ctx.restore();
}
